 const moving=['approach','return'].includes(audience.phase),back=audience.phase==='return';
 const title=right?'主子奶奶':'主子爷',words=[`${title}，奴才给您磕头`,`${title}，奴才给您挡灾`,`感谢${title}大恩`];
