 const revisionFor=id=>journal.memberRevisions?.[id]??journal.events.filter(e=>e.memberId===id).length+(journal.acks[id]||[]).length;
 const save=async(next,id)=>{next.memberRevisions??={};for(const m of roster)next.memberRevisions[m.id]??=revisionFor(m.id);if(id)next.memberRevisions[id]=(next.memberRevisions[id]||0)+1;next.revision++;await atomic(file,Buffer.from(JSON.stringify(next)));journal=next;};
